(function(){'use strict';
/* JAH The Fluid Dynamics Signature generator — jahdb-fluid-dynamics-signature-1.0.
   Property of Justin Addam Higgins (JAH).
   Deterministic: same seed, same record. */
var PREFIX='JAH-FLDYS-';
var FIELDS=["Foundations","Compounded","Advanced"];
var TOPICS=[{"tier": "Foundations", "g": "Fundamentals", "title": "Fluid Properties and the Continuum Hypothesis", "desc": "A fluid is a substance that deforms continuously under any applied shear stress, no matter how small. That single definition separates fluids - liquids and gases - from solids, and it is the starting point of everything in fluid dynamics. The key properties are density (mass per unit volume), specific weight, viscosity (resistance to shear), surface tension, vapor pressure, and compressibility.\nThe continuum hypothesis treats the fluid as a continuous medium rather than a collection of discrete molecules, which lets us define properties like velocity and pressure at a mathematical point. It holds whenever the Knudsen number - the ratio of molecular mean free path to a characteristic length - is much less than one. For air at standard conditions the mean free path is about 68 nanometers, so continuum theory works down to micron-scale devices before rarefied-gas effects appear.", "how": "Engineers use property tables and equations of state to get density and viscosity at operating conditions, then apply the continuum assumption to write differential control-volume balances. Density links mass and volume in every conservation law; viscosity sets the shear stress through Newton's law of viscosity and decides whether a flow is dominated by inertia or friction. Vapor pressure predicts cavitation - where local pressure drops below it, vapor bubbles form and collapse violently. Compressibility, measured by the bulk modulus, decides whether density can be treated as constant; for liquids it almost always can, for gases only at low Mach numbers.", "keys": ["A fluid deforms continuously under any shear stress - the defining property of liquids and gases.", "Density, viscosity, surface tension, vapor pressure, and compressibility are the working properties.", "The continuum hypothesis lets properties be defined at a point; it fails only at micro/nano scales.", "Knudsen number far below one means continuum theory applies.", "Vapor pressure controls cavitation; bulk modulus controls compressibility."], "reqs": ["Property data (density, viscosity) at the operating temperature and pressure.", "A characteristic length scale to check the Knudsen number.", "The operating pressure relative to vapor pressure for cavitation checks."], "stds": ["Density and viscosity reported in SI units per NIST SP 811.", "Thermodynamic property data per NIST REFPROP conventions."], "cites": ["White FM. Fluid Mechanics. 9th ed. McGraw-Hill; 2021.", "Munson BR, Young DF, Okiishi TH. Fundamentals of Fluid Mechanics. 8th ed. Wiley; 2021."], "demo": "#!/usr/bin/env python3\n\"\"\"Fluid properties: Knudsen number check for continuum validity.\"\"\"\nmean_free_path_nm = 68.0  # air at standard conditions\nlengths_um = [1000.0, 10.0, 1.0, 0.1]  # characteristic lengths in microns\nprint(\"Continuum check (Kn = mean free path / length):\")\nfor L in lengths_um:\n    kn = (mean_free_path_nm / 1000.0) / L\n    status = \"continuum OK\" if kn < 0.01 else \"rarefied - beware\"\n    print(f\"  L={L:>8} um  Kn={kn:.2e}  {status}\")\n"}, {"tier": "Foundations", "g": "Fundamentals", "title": "Hydrostatics and Pressure Distribution", "desc": "Hydrostatics is the study of fluids at rest, where the only stress is pressure acting normal to any surface. With no motion there is no shear stress, and the pressure at a point is the same in all directions. The fundamental result is the hydrostatic equation: pressure increases with depth at a rate equal to the specific weight of the fluid, dp/dz = -rho*g.\nFor an incompressible liquid this integrates to the familiar p = p0 + rho*g*h. That linear distribution explains manometers, barometers, dams, and submerged gates. The hydrostatic force on a plane surface equals the pressure at the centroid times the area, acting at the center of pressure, which always lies below the centroid for a non-horizontal surface.", "how": "Engineers draw the pressure distribution as a diagram - triangular for a vertical surface under a liquid - and integrate it to get force and moment. For curved surfaces, the horizontal component equals the force on the projected vertical area and the vertical component equals the weight of fluid above the surface plus or minus displaced volumes. Buoyancy is the special case where the net pressure force on a fully surrounded body equals the weight of displaced fluid. Dam design, tank walls, and gate actuators all size from these integrations.", "keys": ["At rest, pressure is the only stress and acts normal to surfaces.", "Pressure grows linearly with depth: p = p0 + rho*g*h for liquids.", "Force on a plane surface equals centroid pressure times area.", "The center of pressure lies below the centroid on inclined surfaces.", "Curved surfaces are handled by horizontal and vertical components."], "reqs": ["Fluid specific weight (rho*g) at operating conditions.", "Surface geometry: area, centroid depth, inclination.", "Reference pressure at the free surface (usually atmospheric)."], "stds": ["Pressure in pascals (SI); gauge vs absolute stated explicitly.", "Hydrostatic load calculations per ASCE 7 load combinations."], "cites": ["Cengel YA, Cimbala JM. Fluid Mechanics: Fundamentals and Applications. 4th ed. McGraw-Hill; 2017.", "White FM. Fluid Mechanics. 9th ed. McGraw-Hill; 2021."], "demo": "#!/usr/bin/env python3\n\"\"\"Hydrostatic force on a vertical rectangular gate.\"\"\"\nrho, g = 999.0, 9.81  # water at ~15 C\nwidth, height, depth_top = 2.0, 3.0, 1.0  # m\nh_c = depth_top + height / 2.0  # centroid depth\nF = rho * g * h_c * (width * height)\nIxx_c = width * height ** 3 / 12.0\ny_p = Ixx_c / (h_c * width * height)  # center of pressure below centroid\nprint(f\"Hydrostatic force: {F/1000:.1f} kN\")\nprint(f\"Center of pressure: {y_p:.3f} m below centroid\")\nprint(f\"Moment about centroid: {F*y_p/1000:.1f} kN-m\")\n"}, {"tier": "Foundations", "g": "Fundamentals", "title": "Buoyancy and Archimedes' Principle", "desc": "Archimedes' principle states that a body immersed in a fluid experiences an upward buoyant force equal to the weight of the fluid it displaces. The principle follows directly from integrating the hydrostatic pressure distribution over the body surface: deeper pressure on the bottom exceeds the pressure on the top by exactly the displaced weight.\nFloating bodies displace a weight of fluid equal to their own weight, and stability depends on the relative positions of the center of gravity and the metacenter. A ship is stable when its metacentric height is positive - the metacenter sits above the center of gravity so that a small heel produces a righting moment. Hydrometers, hot-air balloons, submarines, and offshore platforms all operate on this one principle.", "how": "To analyze a floating body, equate its weight to rho*g*V_displaced to find the draft, then locate the center of buoyancy (centroid of displaced volume) and compute the metacentric height GM = BM - BG, where BM = I/V_displaced uses the waterplane's second moment of area. Positive GM means stable equilibrium with a righting arm that grows with heel angle for small angles. Naval architects iterate hull form to keep GM in a target band: too small and the ship is tender, too large and the motion is uncomfortably stiff.", "keys": ["Buoyant force equals the weight of displaced fluid - always.", "Floating bodies displace their own weight of fluid.", "Stability needs positive metacentric height: metacenter above center of gravity.", "BM = I/V links waterplane shape to stability.", "GM too small is tender; GM too large is stiff and uncomfortable."], "reqs": ["Body weight and center of gravity location.", "Hull geometry for displaced volume and waterplane inertia.", "Fluid density (seawater ~1025 kg/m3, fresh ~1000 kg/m3)."], "stds": ["Stability criteria per IMO intact-stability code for vessels.", "Displacement reported in metric tonnes."], "cites": ["Munson BR, Young DF, Okiishi TH. Fundamentals of Fluid Mechanics. 8th ed. Wiley; 2021.", "White FM. Fluid Mechanics. 9th ed. McGraw-Hill; 2021."], "demo": "#!/usr/bin/env python3\n\"\"\"Buoyancy: draft and metacentric height of a box barge.\"\"\"\nrho, L, B, D = 1025.0, 60.0, 12.0, 4.0  # seawater, length, beam, depth (m)\nweight_t = 1800.0  # tonnes\nV_disp = weight_t * 1000.0 / rho\ndraft = V_disp / (L * B)\nI_wp = L * B ** 3 / 12.0  # waterplane inertia\nBM = I_wp / V_disp\nKB, KG = draft / 2.0, 2.6  # center of buoyancy, center of gravity\nGM = KB + BM - KG\nprint(f\"Draft: {draft:.2f} m, BM: {BM:.2f} m, GM: {GM:.2f} m\")\nprint(\"STABLE\" if GM > 0 else \"UNSTABLE\")\n"}, {"tier": "Foundations", "g": "Fundamentals", "title": "Bernoulli's Principle in Flow", "desc": "Bernoulli's equation is the workhorse of elementary fluid dynamics: along a streamline in steady, incompressible, frictionless flow, the sum of pressure head, velocity head, and elevation head is constant. In pressure units: p + rho*V^2/2 + rho*g*z = constant. Each term is an energy per unit volume - pressure energy, kinetic energy, and potential energy.\nThe equation explains why fast flow means low pressure: carburetors, atomizers, airplane wings at low speed, and Venturi meters all trade velocity for pressure. Its restrictions matter as much as its power - it fails across pumps, turbines, and long pipes where friction or work terms dominate, and it applies along a streamline (or everywhere only if the flow is irrotational).", "how": "Engineers pick two points on a streamline - typically a reservoir surface and a pipe exit - and equate the Bernoulli sums to solve for the unknown velocity or pressure. The velocity head V^2/2g is the Torricelli free-jet result: a tank draining through an orifice reaches sqrt(2*g*h). For real flows, a head-loss term is added between the points, turning Bernoulli into the energy equation. Stagnation pressure, measured by a Pitot tube facing the flow, is the Bernoulli sum at zero velocity and gives airspeed directly.", "keys": ["Along a streamline: p + rho*V^2/2 + rho*g*z is constant (steady, incompressible, frictionless).", "Each term is energy per unit volume: pressure, kinetic, potential.", "Fast flow means low pressure - the Venturi and lift mechanism.", "Add a head-loss term for real flows; the result is the energy equation.", "Pitot tubes read stagnation pressure, which converts directly to velocity."], "reqs": ["Steady flow along an identifiable streamline.", "Incompressible fluid (Mach < 0.3 for gases).", "No shaft work or dominant friction between the two points (or add loss terms)."], "stds": ["Head expressed in meters of fluid; pressure in pascals.", "Airspeed from Pitot-static systems per ASME PTC 19.5."], "cites": ["White FM. Fluid Mechanics. 9th ed. McGraw-Hill; 2021.", "Cengel YA, Cimbala JM. Fluid Mechanics: Fundamentals and Applications. 4th ed. McGraw-Hill; 2017."], "demo": "#!/usr/bin/env python3\n\"\"\"Bernoulli: tank draining through an orifice (Torricelli).\"\"\"\nimport math\ng, h = 9.81, 4.0  # m/s^2, water depth above orifice (m)\nV = math.sqrt(2 * g * h)  # Torricelli velocity\nd = 0.05  # orifice diameter (m)\nCd = 0.62  # discharge coefficient\nQ = Cd * math.pi * d ** 2 / 4 * V\nprint(f\"Jet velocity: {V:.2f} m/s\")\nprint(f\"Flow rate: {Q*1000:.2f} L/s\")\nprint(f\"Velocity head: {V**2/(2*g):.2f} m\")\n"}, {"tier": "Foundations", "g": "Fundamentals", "title": "The Continuity Equation", "desc": "The continuity equation is conservation of mass written for a fluid: what flows into a control volume minus what flows out equals the rate of mass accumulation inside. For steady flow the accumulation is zero, and for incompressible flow density cancels, leaving the volume-flow form A1*V1 = A2*V2 - velocity rises where area shrinks.\nThis is why nozzles accelerate flow, why rivers speed up at narrows, and why a garden hose jet stiffens when you pinch it. In differential form the equation becomes div(rho*V) + d(rho)/dt = 0, the starting point of every CFD solver. Combined with Bernoulli and momentum, continuity closes the set of equations for most elementary analyses.", "how": "Engineers apply continuity at junctions and area changes before touching any other equation: it relates all the velocities in a network from a single known flow rate. In pipe networks it pairs with the energy equation to solve for unknown flows; in compressible flow the full rho*A*V = constant form captures density change through nozzles and shocks. The differential form is discretized in finite-volume codes, where enforcing it cell by cell is what makes the pressure field physical.", "keys": ["Steady incompressible flow: A1*V1 = A2*V2 - area down, velocity up.", "Full form: mass in minus mass out equals accumulation.", "Differential form div(rho*V) + d(rho)/dt = 0 underlies CFD.", "Compressible form keeps density: rho1*A1*V1 = rho2*A2*V2.", "Always applied first at junctions, nozzles, and area changes."], "reqs": ["Defined control volume with known inlets and outlets.", "Steady or explicitly unsteady accounting.", "Density behavior: constant or variable."], "stds": ["Volume flow in m3/s; mass flow in kg/s.", "Control-volume bookkeeping per standard transport-phenomena conventions."], "cites": ["Munson BR, Young DF, Okiishi TH. Fundamentals of Fluid Mechanics. 8th ed. Wiley; 2021.", "Kundu PK, Cohen IM, Dowling DR. Fluid Mechanics. 6th ed. Academic Press; 2015."], "demo": "#!/usr/bin/env python3\n\"\"\"Continuity: velocity through a reducing pipe section.\"\"\"\nimport math\nQ = 0.05  # m3/s\nfor D in (0.20, 0.15, 0.10, 0.06):\n    A = math.pi * D ** 2 / 4\n    V = Q / A\n    print(f\"  D={D:.2f} m  A={A:.4f} m2  V={V:.2f} m/s\")\n"}, {"tier": "Foundations", "g": "Fundamentals", "title": "Viscosity and Newton's Law of Viscosity", "desc": "Viscosity is a fluid's resistance to shear deformation - the internal friction that makes honey pour slowly and air drag on a car. Newton's law of viscosity states that shear stress is proportional to the velocity gradient: tau = mu * du/dy, where mu is the dynamic viscosity. Fluids obeying this linear relation are Newtonian; water, air, and light oils are, while paint, blood, and ketchup are not.\nDynamic viscosity has units of Pa-s; dividing by density gives the kinematic viscosity nu = mu/rho in m2/s, which is what actually diffuses momentum. Liquid viscosity falls steeply with temperature while gas viscosity rises slowly with temperature - opposite trends that matter in lubrication and high-altitude flight. Non-Newtonian fluids need richer models: power-law, Bingham plastic, or viscoelastic.", "how": "Engineers read mu from tables or correlations at the operating temperature, then use Newton's law to get wall shear stress from the near-wall velocity gradient - the origin of skin-friction drag. In lubrication, the thin-film Reynolds equation balances pressure gradients against viscous shear to predict load capacity of journal bearings. Kinematic viscosity appears in the Reynolds number, so getting nu right decides whether a flow is laminar or turbulent. Viscometers - capillary, rotational, falling-ball - measure mu directly for quality control of fuels, oils, and foods.", "keys": ["Newton's law: tau = mu * du/dy; linear for Newtonian fluids.", "Kinematic viscosity nu = mu/rho is what diffuses momentum.", "Liquid viscosity drops with temperature; gas viscosity rises with it.", "Wall shear from the near-wall gradient is the source of skin-friction drag.", "Non-Newtonian fluids (paint, blood, ketchup) need power-law or Bingham models."], "reqs": ["Temperature at operating conditions (viscosity is temperature-sensitive).", "Shear-rate range to confirm Newtonian behavior.", "Density for converting between dynamic and kinematic viscosity."], "stds": ["Viscosity in Pa-s (SI); kinematic viscosity in m2/s.", "Viscometer calibration per ASTM D445 for petroleum products."], "cites": ["White FM. Fluid Mechanics. 9th ed. McGraw-Hill; 2021.", "Bird RB, Stewart WE, Lightfoot EN. Transport Phenomena. 2nd ed. Wiley; 2006."], "demo": "#!/usr/bin/env python3\n\"\"\"Newton law of viscosity: shear stress in a Couette (sliding plate) film.\"\"\"\nmu = 0.48  # Pa-s, SAE 30 oil at ~40 C\nU, h = 3.0, 0.002  # plate speed m/s, film thickness m\ntau = mu * U / h  # linear profile\nA = 0.5  # plate area m2\nprint(f\"Shear stress: {tau:.0f} Pa\")\nprint(f\"Drag force: {tau*A:.0f} N, power: {tau*A*U:.0f} W\")\n"}, {"tier": "Foundations", "g": "Fundamentals", "title": "Laminar Flow in Pipes", "desc": "In a straight circular pipe at low Reynolds number, flow is laminar: fluid moves in smooth concentric layers with a parabolic velocity profile, fastest at the center and zero at the wall. The exact solution - Hagen-Poiseuille flow - gives volume flow rate Q = pi*D^4*dp/(128*mu*L), showing the famous fourth-power dependence on diameter: doubling a pipe's diameter cuts the pressure drop sixteen-fold at the same flow.\nThe Darcy friction factor in laminar flow is simply f = 64/Re, independent of roughness because the smooth layers never feel the wall texture. Entrance length - the distance for the profile to develop - is about 0.05*Re*D. Below Re ~ 2300 the flow stays laminar; above ~4000 it is turbulent, with a transition zone between where small disturbances decide.", "how": "Engineers use Hagen-Poiseuille for microfluidics, capillary viscometers, and slow viscous flows like heavy oil or blood in small vessels. For design, they compute Re = rho*V*D/mu, check it is below 2300, then get pressure drop from dp = 32*mu*L*V/D^2 or the f = 64/Re form of Darcy-Weisbach. Because of the D^4 scaling, laminar systems are exquisitely sensitive to diameter - a slightly undersized line in a hydraulic system creates huge losses. Syringes, inkjet nozzles, and porous media flows all live in this regime.", "keys": ["Laminar pipe flow has a parabolic profile; Q scales with D^4.", "Friction factor f = 64/Re, independent of wall roughness.", "Laminar below Re ~ 2300, turbulent above ~4000.", "Entrance length ~ 0.05*Re*D for profile development.", "Diameter sensitivity is extreme - small changes dominate pressure drop."], "reqs": ["Reynolds number to confirm the laminar regime.", "Pipe diameter, length, fluid viscosity and density.", "Fully developed flow (or entrance-length correction)."], "stds": ["Pressure drop per Darcy-Weisbach with SI units.", "Pipe roughness and diameter per ASME B36.10M."], "cites": ["White FM. Fluid Mechanics. 9th ed. McGraw-Hill; 2021.", "Munson BR, Young DF, Okiishi TH. Fundamentals of Fluid Mechanics. 8th ed. Wiley; 2021."], "demo": "#!/usr/bin/env python3\n\"\"\"Hagen-Poiseuille: pressure drop in a laminar oil line.\"\"\"\nimport math\nrho, mu = 880.0, 0.48  # kg/m3, Pa-s\nD, L, V = 0.05, 20.0, 0.4  # m, m, m/s\nRe = rho * V * D / mu\ndp = 32 * mu * L * V / D ** 2\nprint(f\"Re = {Re:.0f} ({chr(34)+chr(34)})\".replace(chr(34)+chr(34), \"laminar\" if Re<2300 else \"CHECK\"))\nprint(f\"Pressure drop: {dp/1000:.1f} kPa over {L} m\")\nprint(f\"f = 64/Re = {64/Re:.4f}\")\n"}, {"tier": "Foundations", "g": "Fundamentals", "title": "The Reynolds Number", "desc": "The Reynolds number, Re = rho*V*L/mu, is the most important dimensionless group in fluid mechanics: the ratio of inertial forces to viscous forces. Low Re means viscosity rules and flow is smooth and predictable; high Re means inertia rules and flow tends toward turbulence. It is the number that lets a wind-tunnel model predict a full-size airplane.\nThe characteristic length L depends on the geometry: diameter for pipes, chord for airfoils, length for flat plates. Critical values mark transitions - about 2300 in pipes, about 5x10^5 on a flat plate. Two flows with the same Re and geometry are dynamically similar: their dimensionless velocity fields match, which is the entire basis of scale-model testing.", "how": "Engineers compute Re first in almost every analysis because it chooses the tools: laminar correlations below transition, turbulent models above. In testing, they match Re between model and prototype by adjusting velocity, size, or fluid - pressurized or cryogenic tunnels raise density to hit flight Re on small models. Microfluidic devices deliberately operate at Re < 1, where flow is reversible and mixing must be engineered geometrically. The number also appears inside every friction, drag, and heat-transfer correlation.", "keys": ["Re = rho*V*L/mu: inertia versus viscosity.", "Low Re is smooth and laminar; high Re tends turbulent.", "Critical Re ~ 2300 (pipe), ~5e5 (flat plate).", "Equal Re plus geometric similarity gives dynamic similarity.", "Matching Re is the basis of all scale-model testing."], "reqs": ["Characteristic velocity, length, density, viscosity.", "Geometry-specific critical Re for the transition check.", "Decision on which similarity groups to match in model testing."], "stds": ["Dimensionless groups reported per standard fluid-mechanics notation.", "Model-test similarity per AIAA wind-tunnel testing practice."], "cites": ["White FM. Fluid Mechanics. 9th ed. McGraw-Hill; 2021.", "Kundu PK, Cohen IM, Dowling DR. Fluid Mechanics. 6th ed. Academic Press; 2015."], "demo": "#!/usr/bin/env python3\n\"\"\"Reynolds number across everyday flows.\"\"\"\ncases = [(\"Water pipe\", 999, 1.5, 0.1, 1.0e-3),\n        (\"Air over wing\", 1.2, 70.0, 2.0, 1.8e-5),\n        (\"Microchannel\", 1000, 0.01, 100e-6, 1.0e-3),\n        (\"Swimming human\", 999, 1.5, 1.8, 1.0e-3)]\nfor name, rho, V, L, mu in cases:\n    Re = rho * V * L / mu\n    print(f\"{name:15s} Re = {Re:.2e}\")\n"}, {"tier": "Foundations", "g": "Fundamentals", "title": "Streamlines, Streaklines, and Pathlines", "desc": "Three different curves describe flow patterns, and they coincide only in steady flow. A streamline is tangent to the velocity field at one instant - a snapshot of flow direction. A pathline is the trajectory one fluid particle traces over time. A streakline is the locus of all particles that passed through one point - what dye injected continuously from a fixed point reveals.\nIn steady flow the velocity field never changes, so all three collapse into one family of curves and a smoke-wire photograph reads directly as the flow pattern. In unsteady flow they differ dramatically: behind a flapping wing, the streakline shows rolled-up vortices while instantaneous streamlines look entirely different. Confusing them is a classic error in interpreting visualization.", "how": "Experimentalists choose visualization to match the question: smoke or dye streaklines for wake structure, particle-image velocimetry for instantaneous streamlines, particle tracking for pathlines and dispersion. CFD post-processors integrate the velocity field to draw streamlines from seed points, and time-integrate particle positions for pathlines and streaklines. No streamline ever crosses another in steady flow, and streamlines crowd where velocity is high - a quick visual check of any computed field.", "keys": ["Streamline: tangent to velocity at an instant. Pathline: one particle's history. Streakline: dye-line locus.", "All three coincide only in steady flow.", "Smoke and dye photographs show streaklines.", "PIV gives instantaneous streamlines; particle tracking gives pathlines.", "Streamlines never cross and crowd where flow is fast."], "reqs": ["Steady or unsteady classification of the flow.", "Velocity field data (measured or computed) for integration.", "Visualization method matched to the question: streakline, streamline, or pathline."], "stds": ["Flow-visualization reporting per AIAA visualization guidelines.", "PIV uncertainty quantified per standard PIV practice."], "cites": ["Kundu PK, Cohen IM, Dowling DR. Fluid Mechanics. 6th ed. Academic Press; 2015.", "Munson BR, Young DF, Okiishi TH. Fundamentals of Fluid Mechanics. 8th ed. Wiley; 2021."], "demo": "#!/usr/bin/env python3\n\"\"\"Streamlines of uniform flow plus a source (Rankine half-body seed).\"\"\"\nimport math\nU, m = 1.0, 0.5  # uniform speed, source strength\nprint(\"Stagnation point at x =\", -m / U)\nfor y in (0.5, 1.0, 2.0):\n    psi = U * y + m * math.atan2(y, 1.0)\n    print(f\"  streamline through (1,{y}): psi = {psi:.3f}\")\n"}, {"tier": "Foundations", "g": "Fundamentals", "title": "Manometry and Pressure Measurement", "desc": "Manometers measure pressure from the height of a liquid column, using the hydrostatic relation p = rho*g*h directly - no calibration against another instrument needed. The U-tube manometer reads differential pressure between its two legs; the well type reads one leg against a large reservoir; the inclined tube stretches small pressures over a longer scale for readability.\nChoosing the manometer fluid sets the range: water for small pressures, mercury for large ones, light oils for tiny drafts. Modern practice adds electronic transducers - piezoresistive, capacitive, and piezoelectric - for speed and logging, but manometers remain the primary standard in calibration labs because the physics is exact. Barometers are simply manometers open to the atmosphere on one side.", "how": "Technicians read the difference in column heights, multiply by rho*g of the manometer fluid, and correct for temperature (density changes) and local gravity in precision work. In HVAC and combustion testing, inclined manometers read draft pressures of a few pascals that transducers would bury in noise. Pitot-static tubes pair with manometers or transducers to get velocity from stagnation minus static pressure. Multi-tube manometers map pressure distributions over wings and buildings in wind tunnels simultaneously.", "keys": ["Manometers read pressure from liquid column height: p = rho*g*h.", "U-tube reads differential; well type and inclined tube extend the range.", "Fluid choice sets range: water, mercury, or light oils.", "Manometers remain primary standards because the physics needs no calibration.", "Temperature and gravity corrections matter in precision work."], "reqs": ["Manometer fluid density at ambient temperature.", "Column height difference, read at the meniscus bottom.", "Local gravity for primary-standard accuracy."], "stds": ["Pressure calibration per ASME PTC 19.2.", "Transducer calibration traceable to primary manometer standards."], "cites": ["White FM. Fluid Mechanics. 9th ed. McGraw-Hill; 2021.", "Figliola RS, Beasley DE. Theory and Design for Mechanical Measurements. 7th ed. Wiley; 2019."], "demo": "#!/usr/bin/env python3\n\"\"\"U-tube manometer: differential pressure from column height.\"\"\"\nrho, g = 1000.0, 9.81  # water\nfor dh_mm in (5, 25, 120):\n    dp = rho * g * dh_mm / 1000.0\n    print(f\"  dh = {dh_mm} mm water  ->  dp = {dp:.1f} Pa ({dp/1000:.3f} kPa)\")\n"}, {"tier": "Foundations", "g": "Fundamentals", "title": "Surface Tension and Capillarity", "desc": "Surface tension is the energy per unit area of a liquid-gas interface, arising because surface molecules lack neighbors on one side. It lets water striders walk, forms droplets, and drives capillary rise: in a narrow tube, the curved meniscus supports a liquid column of height h = 2*sigma*cos(theta)/(rho*g*r), higher for smaller tubes.\nThe Young-Laplace equation gives the pressure jump across a curved interface: dp = sigma*(1/R1 + 1/R2), which is 2*sigma/R for a spherical droplet. Surfactants lower surface tension and are the active agents in detergents. At large scales gravity dominates and surface tension is negligible; at millimeter scales and below - inkjets, microfluidics, plant xylem - it rules.", "how": "Engineers compute capillary rise to predict wicking in porous media, soils, and paper; the same physics sets the pore size that a fuel-cell gas-diffusion layer must have. Droplet formation in sprays and inkjets balances surface tension against inertia via the Weber number. Contact angle hysteresis explains why droplets stick on windshields. In welding and soldering, flux modifies surface tension to let molten metal wet the joint.", "keys": ["Surface tension is interface energy per unit area from unbalanced molecular forces.", "Capillary rise: h = 2*sigma*cos(theta)/(rho*g*r) - smaller tube, higher rise.", "Young-Laplace: pressure jumps across curved interfaces, dp = 2*sigma/R for droplets.", "Surfactants lower surface tension; detergents work this way.", "Surface tension dominates at small scales, gravity at large ones."], "reqs": ["Surface tension sigma and contact angle theta for the liquid-solid pair.", "Tube or pore radius.", "Cleanliness - contamination changes sigma dramatically."], "stds": ["Surface tension in N/m (SI).", "Contact-angle measurement per ASTM D7334."], "cites": ["White FM. Fluid Mechanics. 9th ed. McGraw-Hill; 2021.", "de Gennes PG, Brochard-Wyart F, Quere D. Capillarity and Wetting Phenomena. Springer; 2003."], "demo": "#!/usr/bin/env python3\n\"\"\"Capillary rise of water in glass tubes.\"\"\"\nimport math\nsigma, theta, rho, g = 0.073, 0.0, 999.0, 9.81  # N/m, rad, kg/m3, m/s2\nfor r_mm in (1.0, 0.5, 0.1, 0.02):\n    h = 2 * sigma * math.cos(theta) / (rho * g * r_mm / 1000.0)\n    print(f\"  radius {r_mm} mm -> rise {h*1000:.1f} mm\")\n"}, {"tier": "Foundations", "g": "Fundamentals", "title": "Dimensional Analysis and the Buckingham Pi Theorem", "desc": "Dimensional analysis collapses a problem's variables into fewer dimensionless groups, revealing which combinations actually matter. The Buckingham Pi theorem states that a relation among n variables with k fundamental dimensions reduces to n-k independent dimensionless pi groups. Drag on a sphere depending on V, D, rho, mu (5 variables, 3 dimensions) becomes drag coefficient as a function of Reynolds number alone.\nThe method cannot produce the function's form - experiments or theory must supply that - but it slashes test matrices and exposes scaling laws. The classic groups - Reynolds, Froude, Mach, Weber, Strouhal - each name a force ratio, and matching the right ones is what makes model tests valid. It is also a ruthless error check: any equation whose terms differ in dimension is wrong.", "how": "Analysts list every variable that could matter, form the pi groups by the repeating-variable method, then design experiments varying one group at a time. In ship testing, Froude similarity (gravity waves) is matched and viscous corrections applied because both Re and Fr cannot be matched at once at small scale. In compressible aerodynamics, Mach and Reynolds are the pair to match. Every correlation in heat transfer and fluid mechanics - Nusselt vs Reynolds and Prandtl - is a dimensional-analysis product.", "keys": ["n variables and k dimensions reduce to n-k dimensionless groups.", "Sphere drag becomes Cd = f(Re) - one curve instead of five variables.", "Classic groups name force ratios: Re, Fr, Ma, We, St.", "The method gives the groups, not the function - data supplies that.", "Dimension checking catches wrong equations instantly."], "reqs": ["Complete variable list - omitting one breaks the analysis.", "Fundamental dimensions (M, L, T, temperature).", "Repeating variables spanning all dimensions."], "stds": ["Dimensionless groups in standard notation (Re, Fr, Ma).", "Scaling analysis documented per AIAA test standards."], "cites": ["White FM. Fluid Mechanics. 9th ed. McGraw-Hill; 2021.", "Kundu PK, Cohen IM, Dowling DR. Fluid Mechanics. 6th ed. Academic Press; 2015."], "demo": "#!/usr/bin/env python3\n\"\"\"Pi groups for pipe pressure drop: dp = f(D,L,V,rho,mu,eps).\"\"\"\n# n=7 variables, k=3 dimensions -> 4 pi groups\ngroups = [\"dp/(rho V^2)  (Euler/pressure coeff)\", \"L/D (geometry)\",\n          \"rho V D/mu = Re\", \"eps/D (roughness)\"]\nprint(\"7 variables - 3 dimensions = 4 pi groups:\")\nfor i, g in enumerate(groups, 1):\n    print(f\"  Pi{i}: {g}\")\nprint(\"So: dp/(rho V^2) = F(L/D, Re, eps/D) - the Moody chart.\")\n"}, {"tier": "Compounded", "g": "Viscous Flows", "title": "The Navier-Stokes Equations", "desc": "The Navier-Stokes equations are Newton's second law written for a fluid particle: mass times acceleration equals pressure forces plus viscous forces plus body forces. In compact form, rho*(dV/dt + V.grad V) = -grad p + mu*laplacian V + rho*g. They are the complete description of Newtonian fluid motion, and nearly every result in fluid mechanics is a special case of them.\nExact solutions are rare - Couette flow, Poiseuille flow, Stokes flow - because the nonlinear convective term V.grad V resists analysis. Existence and smoothness of solutions in three dimensions remains a Millennium Prize problem. In practice the equations are solved numerically (CFD) or simplified by dropping terms: inviscid gives Euler, creeping flow drops inertia, boundary-layer theory drops selected viscous terms.", "how": "Engineers rarely solve the full equations by hand; instead they non-dimensionalize to reveal the Reynolds number, then choose the right simplification. High Re with thin viscous regions becomes boundary-layer theory; Re << 1 becomes Stokes flow with linear equations. CFD discretizes the equations on a mesh and iterates to convergence, with turbulence models closing the averaged equations. Every pump curve, airfoil polar, and pipe-loss correlation is ultimately a Navier-Stokes solution in disguise.", "keys": ["Newton's second law per unit volume: inertia = pressure + viscous + body forces.", "The nonlinear convective term is what makes the equations hard.", "Exact solutions exist only for simple geometries; 3D smoothness is an open math problem.", "Euler, Stokes, and boundary-layer equations are all simplifications of Navier-Stokes.", "Non-dimensionalizing exposes the Reynolds number as the key parameter."], "reqs": ["Newtonian fluid with known density and viscosity.", "Boundary conditions: no-slip at solid walls, known inlets/outlets.", "Decision on simplifications: inviscid, creeping, or full numerical."], "stds": ["Equations written in conservative form for CFD per standard practice.", "Verification against exact solutions (Method of Manufactured Solutions)."], "cites": ["Kundu PK, Cohen IM, Dowling DR. Fluid Mechanics. 6th ed. Academic Press; 2015.", "White FM. Viscous Fluid Flow. 3rd ed. McGraw-Hill; 2005."], "demo": "#!/usr/bin/env python3\n\"\"\"Navier-Stokes check: Couette flow satisfies the x-momentum equation.\"\"\"\nimport math\nmu, dpdx, h = 0.01, -50.0, 0.02  # Pa-s, Pa/m, m\n# Plane Poiseuille profile: u(y) = -dpdx/(2 mu) * y (h - y)\nys = [i * h / 8 for i in range(9)]\nprint(\" y (mm)   u (m/s)   viscous term = -dpdx ?\")\nfor y in ys:\n    u = -dpdx / (2 * mu) * y * (h - y)\n    visc = mu * (-dpdx / mu)  # mu*d2u/dy2 = -dpdx exactly\n    print(f\"  {y*1000:5.1f}   {u:7.4f}   {visc:.1f} = {-dpdx:.1f} OK\")\n"}, {"tier": "Compounded", "g": "Viscous Flows", "title": "Boundary Layer Theory", "desc": "Ludwig Prandtl's 1904 boundary-layer concept resolved the paradox of inviscid theory predicting zero drag: viscosity matters only in a thin layer near solid surfaces, where velocity rises from zero at the wall (no-slip) to the free-stream value. Outside the layer the flow is effectively inviscid; inside, steep gradients produce skin friction.\nFor a laminar flat plate the Blasius solution gives thickness delta ~ 5x/sqrt(Re_x) and skin friction cf = 0.664/sqrt(Re_x). The layer grows with distance, transitions to turbulence around Re_x ~ 5x10^5, and separates when an adverse pressure gradient slows near-wall fluid to a stop - the cause of stall on wings and losses in diffusers.", "how": "Engineers estimate drag by integrating skin friction over wetted area, using laminar Blasius results upstream of transition and turbulent correlations downstream. Separation is delayed with suction, blowing, vortex generators, or shaping that keeps pressure gradients favorable. In CFD, resolving the boundary layer demands fine near-wall mesh (y+ ~ 1) or wall functions. Heat transfer follows the same layer structure - the thermal boundary layer - so the same theory sizes heat exchangers.", "keys": ["Viscosity acts in a thin layer near walls; outside is effectively inviscid.", "No-slip: velocity is zero at the wall, rising to free-stream at the edge.", "Laminar Blasius: delta ~ 5x/sqrt(Re_x), cf = 0.664/sqrt(Re_x).", "Adverse pressure gradients cause separation - the mechanism of stall.", "Transition on a smooth plate occurs near Re_x ~ 5x10^5."], "reqs": ["Free-stream velocity and fluid properties for Re_x.", "Surface condition: smooth or rough, heated or insulated.", "Pressure-gradient history along the surface."], "stds": ["Skin-friction reporting per standard boundary-layer notation.", "y+ < 1 for wall-resolved CFD per best-practice guidelines."], "cites": ["Schlichting H, Gersten K. Boundary-Layer Theory. 9th ed. Springer; 2017.", "White FM. Viscous Fluid Flow. 3rd ed. McGraw-Hill; 2005."], "demo": "#!/usr/bin/env python3\n\"\"\"Blasius laminar boundary layer on a flat plate.\"\"\"\nimport math\nU, nu = 10.0, 1.5e-5  # m/s, m2/s (air)\nprint(\"   x (m)   Re_x      delta (mm)  cf\")\nfor x in (0.1, 0.5, 1.0, 2.0):\n    Rex = U * x / nu\n    delta = 5.0 * x / math.sqrt(Rex)\n    cf = 0.664 / math.sqrt(Rex)\n    print(f\"  {x:6.1f}  {Rex:.2e}   {delta*1000:7.2f}   {cf:.5f}\")\n"}, {"tier": "Compounded", "g": "Viscous Flows", "title": "Pipe Flow and the Moody Chart", "desc": "Real pipe flow is turbulent more often than not, and the Moody chart is the engineer's map of it: the Darcy friction factor f plotted against Reynolds number with relative roughness epsilon/D as parameter. Four regimes appear - laminar (f = 64/Re), smooth turbulent (Blasius), transitional, and fully rough where f flattens to a roughness-only value.\nHead loss follows Darcy-Weisbach: h_L = f*(L/D)*(V^2/2g), plus minor losses K*(V^2/2g) for valves, bends, and entrances. The energy equation with these losses sizes every water distribution system, oil pipeline, and HVAC duct network. Roughness values are tabulated for commercial steel, cast iron, concrete, and plastic pipe.", "how": "Designers compute Re and epsilon/D, read or compute f (Colebrook equation solved iteratively, or the explicit Haaland approximation), then get head loss and required pump head. For existing systems the same equations run backward: measured pressure drop reveals the flow rate or diagnoses fouling when f drifts above the clean-pipe value. Pipe networks are solved by enforcing continuity at nodes and zero net head loss around loops - the Hardy-Cross method or modern solvers.", "keys": ["Moody chart: f vs Re with roughness parameter - four regimes.", "Darcy-Weisbach: h_L = f*(L/D)*(V^2/2g); add minor losses K*(V^2/2g).", "Colebrook/Haaland gives f explicitly for turbulent flow.", "Fully rough regime: f depends on roughness alone, not Re.", "Rising f over time diagnoses fouling or corrosion."], "reqs": ["Flow rate, pipe diameter, length, fluid properties.", "Pipe roughness epsilon for the material and age.", "Minor-loss coefficients for fittings."], "stds": ["Head loss per Darcy-Weisbach; roughness per standard pipe tables.", "Pump sizing per Hydraulic Institute standards."], "cites": ["White FM. Fluid Mechanics. 9th ed. McGraw-Hill; 2021.", "Munson BR, Young DF, Okiishi TH. Fundamentals of Fluid Mechanics. 8th ed. Wiley; 2021."], "demo": "#!/usr/bin/env python3\n\"\"\"Haaland friction factor and head loss in a water main.\"\"\"\nimport math\nrho, mu = 999.0, 1.0e-3\nD, L, eps, V = 0.3, 1000.0, 0.045e-3, 2.0\nRe = rho * V * D / mu\nf = (-1.8 * math.log10((eps / D / 3.7) ** 1.11 + 6.9 / Re)) ** -2  # Haaland\nhL = f * (L / D) * V ** 2 / (2 * 9.81)\nprint(f\"Re = {Re:.2e}, f = {f:.4f}\")\nprint(f\"Head loss: {hL:.1f} m over {L:.0f} m ({hL/L*100:.2f} m per 100 m)\")\n"}, {"tier": "Compounded", "g": "Fundamentals", "title": "Drag and Lift on Bodies", "desc": "Any body in a flow feels drag along the flow direction and lift across it, expressed through dimensionless coefficients: F_D = C_D * (rho*V^2/2) * A. Drag splits into skin friction (viscous shear on the surface) and pressure or form drag (the wake's low pressure pulling backward). Streamlined bodies minimize form drag; bluff bodies like trucks are dominated by it.\nLift on wings comes from pressure differences - faster flow and lower pressure above, slower below - quantified by C_L, which grows with angle of attack until stall. The drag polar C_D vs C_L maps the tradeoff every aircraft designer lives with. The same coefficients size parachutes, size cyclists' aerodynamics, and predict wind loads on buildings.", "how": "Engineers get C_D and C_L from wind-tunnel tests, CFD, or empirical correlations, then scale forces with dynamic pressure q = rho*V^2/2. Vehicle designers chase lower C_D*A through shaping, underbody panels, and wake control. Wing designers pick airfoils and planforms from polar data to hit cruise lift-to-drag ratios of 15-20 for airliners. Sports engineers use the same numbers: a golf ball's dimples trip the boundary layer turbulent, shrinking the wake and cutting drag.", "keys": ["F = C * q * A with q = rho*V^2/2 - coefficients scale everything.", "Drag = skin friction + form (pressure) drag.", "Lift coefficient rises with angle of attack until stall.", "Streamlining attacks form drag; smooth surfaces attack friction drag.", "Dimples, trip strips, and shaping all manage the boundary layer and wake."], "reqs": ["Reference area convention (frontal for cars, planform for wings).", "Reynolds number for the coefficient's validity range.", "Angle of attack for lift data."], "stds": ["Force coefficients per AIAA standard notation.", "Wind-tunnel corrections per standard test practice."], "cites": ["Anderson JD. Fundamentals of Aerodynamics. 6th ed. McGraw-Hill; 2016.", "White FM. Fluid Mechanics. 9th ed. McGraw-Hill; 2021."], "demo": "#!/usr/bin/env python3\n\"\"\"Drag force and power for a car at highway speeds.\"\"\"\nrho, Cd, A = 1.2, 0.30, 2.2  # kg/m3, -, m2\nprint(\"  V (km/h)   Drag (N)   Power (kW)\")\nfor vkmh in (60, 90, 120, 150):\n    V = vkmh / 3.6\n    F = Cd * 0.5 * rho * V ** 2 * A\n    print(f\"  {vkmh:6d}    {F:7.0f}    {F*V/1000:6.1f}\")\n"}, {"tier": "Compounded", "g": "Fundamentals", "title": "Potential Flow Theory", "desc": "Potential flow assumes inviscid, incompressible, irrotational flow, which lets the velocity field be written as the gradient of a scalar potential satisfying Laplace's equation. Solutions superpose: uniform flow plus sources, sinks, vortices, and doublets build up flow around cylinders, airfoils, and Rankine bodies analytically.\nThe theory predicts pressure distributions and lift (via the Kutta-Joukowski theorem, L = rho*V*Gamma) surprisingly well outside boundary layers, but it also predicts zero drag - d'Alembert's paradox - because it ignores viscosity entirely. Panel methods, the workhorse of preliminary aerodynamic design, are potential flow discretized onto surface panels with viscous corrections added after.", "how": "Aerodynamicists superpose elementary solutions to sketch flows in minutes: a source in uniform flow makes a Rankine half-body; source plus sink makes a Rankine oval; doublet plus uniform flow plus vortex makes lifting flow over a cylinder. The Kutta condition sets circulation on airfoils by requiring smooth flow off the trailing edge, which selects the physical lift from infinite mathematical possibilities. Modern panel codes extend this to full aircraft configurations before expensive viscous CFD.", "keys": ["Inviscid + irrotational gives Laplace's equation for a velocity potential.", "Elementary flows superpose: sources, sinks, vortices, doublets.", "Kutta-Joukowski: lift = rho*V*circulation.", "d'Alembert's paradox: potential flow predicts zero drag.", "Panel methods are discretized potential flow - fast preliminary design."], "reqs": ["Inviscid, incompressible, irrotational assumptions stated.", "Kutta condition to fix circulation on lifting bodies.", "Viscous corrections for drag and stall."], "stds": ["Potential-flow solutions reported with circulation and pressure coefficient.", "Panel-method verification against analytic cylinder/oval cases."], "cites": ["Anderson JD. Fundamentals of Aerodynamics. 6th ed. McGraw-Hill; 2016.", "Kundu PK, Cohen IM, Dowling DR. Fluid Mechanics. 6th ed. Academic Press; 2015."], "demo": "#!/usr/bin/env python3\n\"\"\"Potential flow over a cylinder: surface pressure coefficient.\"\"\"\nimport math\n# Cp = 1 - 4 sin^2(theta) for non-lifting cylinder\nprint(\" theta(deg)   Cp\")\nfor deg in range(0, 181, 30):\n    th = math.radians(deg)\n    Cp = 1 - 4 * math.sin(th) ** 2\n    print(f\"  {deg:6d}    {Cp:+.2f}\")\n"}, {"tier": "Compounded", "g": "Fundamentals", "title": "Vorticity and Circulation", "desc": "Vorticity is the curl of the velocity field - twice the local angular velocity of a fluid element - and it marks where rotation lives: boundary layers, wakes, and vortices. Circulation is the line integral of velocity around a closed curve, and the two link through Stokes' theorem: circulation equals the flux of vorticity through the enclosed surface.\nKelvin's circulation theorem says circulation around a material curve is conserved in inviscid barotropic flow, which explains why starting vortices form when lift develops - the bound vortex on the wing demands an equal-and-opposite starting vortex downstream. Helmholtz's theorems describe how vortex lines move with the fluid and cannot end inside it, the basis of wingtip-vortex and tornado analysis.", "how": "Aerodynamicists compute lift from bound circulation via Kutta-Joukowski and trace shed vorticity into wakes to predict induced drag and wake encounters behind aircraft. Meteorologists track vorticity in weather models - cyclones are vorticity concentrations, and potential vorticity is conserved following the flow. In CFD, vorticity plots reveal separation, vortex shedding, and turbulence structure far more clearly than velocity plots. Vortex methods simulate flows by tracking vortex elements instead of meshing everything.", "keys": ["Vorticity = curl of velocity; circulation = line integral of velocity.", "Stokes' theorem links them: circulation equals vorticity flux.", "Kelvin's theorem: circulation is conserved in inviscid flow.", "Lift requires bound circulation; starting vortices balance it.", "Vortex lines move with the fluid and cannot end mid-flow."], "reqs": ["Velocity field data for curl computation.", "Closed curve choice for circulation integrals.", "Inviscid-flow assumption check for Kelvin/Helmholtz application."], "stds": ["Vorticity reported in 1/s; circulation in m2/s.", "Vortex identification per standard criteria (Q, lambda-2)."], "cites": ["Kundu PK, Cohen IM, Dowling DR. Fluid Mechanics. 6th ed. Academic Press; 2015.", "Anderson JD. Fundamentals of Aerodynamics. 6th ed. McGraw-Hill; 2016."], "demo": "#!/usr/bin/env python3\n\"\"\"Circulation of a point vortex and induced velocity.\"\"\"\nimport math\nGamma = 5.0  # m2/s\nprint(\"  r (m)   V_theta (m/s)   circulation check\")\nfor r in (0.5, 1.0, 2.0, 5.0):\n    Vt = Gamma / (2 * math.pi * r)\n    circ = Vt * 2 * math.pi * r\n    print(f\"  {r:5.1f}   {Vt:10.3f}      {circ:.3f} = Gamma OK\")\n"}, {"tier": "Compounded", "g": "Compressible Flows", "title": "Compressible Flow and Mach Number", "desc": "When flow speeds approach the speed of sound, density changes can no longer be ignored and the Mach number M = V/a becomes the governing parameter. Below M ~ 0.3 density varies by less than 5% and incompressible theory works; above that, compressible relations take over. The speed of sound a = sqrt(k*R*T) rises with temperature, so Mach number depends on thermal state, not just speed.\nSubsonic, transonic, supersonic, and hypersonic regimes each have distinct physics: pressure signals cannot propagate upstream in supersonic flow, creating zones of silence and action. Isentropic relations link pressure, density, and temperature ratios to Mach number for the idealized frictionless, adiabatic case that anchors all compressible analysis.", "how": "Engineers compute Mach number first to choose the theory: incompressible below 0.3, compressible isentropic relations through the transonic range, shock-expansion theory for supersonic. Pitot tubes in supersonic flow need the Rayleigh supersonic Pitot formula because a normal shock stands ahead of the probe. Nozzle design uses area-Mach relations to shape converging-diverging passages. Aircraft performance, from propeller tips to inlets, is organized by Mach number throughout.", "keys": ["M = V/a; compressibility matters above M ~ 0.3.", "Speed of sound a = sqrt(k*R*T) depends on temperature.", "Supersonic flow cannot send pressure signals upstream.", "Isentropic relations link p, rho, T ratios to Mach number.", "Mach number organizes all high-speed aerodynamics."], "reqs": ["Static temperature for the speed of sound.", "Specific heat ratio k (1.4 for air).", "Stagnation vs static property discipline."], "stds": ["Mach number dimensionless; standard-atmosphere tables per ISO 2533.", "Compressible flow notation per NACA/AIAA conventions."], "cites": ["Anderson JD. Modern Compressible Flow. 3rd ed. McGraw-Hill; 2002.", "White FM. Fluid Mechanics. 9th ed. McGraw-Hill; 2021."], "demo": "#!/usr/bin/env python3\n\"\"\"Isentropic relations: pressure ratio vs Mach number (air, k=1.4).\"\"\"\nk = 1.4\nprint(\"   M     p0/p     T0/T     rho0/rho\")\nfor M in (0.3, 0.8, 1.0, 1.5, 2.0, 3.0):\n    t = 1 + (k - 1) / 2 * M ** 2\n    p0p = t ** (k / (k - 1))\n    print(f\"  {M:.1f}   {p0p:7.2f}   {t:6.3f}    {p0p/t:7.2f}\")\n"}, {"tier": "Compounded", "g": "Compressible Flows", "title": "Normal Shock Waves", "desc": "A normal shock is a nearly discontinuous jump in pressure, density, and temperature that forms when supersonic flow must slow to subsonic - ahead of a Pitot tube, in a supersonic inlet, or in an overexpanded nozzle. Across the shock, mass, momentum, and energy conserve while entropy rises; the process is adiabatic but irreversible.\nThe normal-shock relations give downstream Mach number and property ratios purely as functions of upstream Mach number: pressure and temperature jump up, velocity drops, and total pressure falls - the loss that makes shock-free deceleration valuable. Stronger upstream Mach means stronger shocks and larger total-pressure losses, which is why supersonic inlets use sequences of weak oblique shocks instead of one normal shock.", "how": "Designers place shocks deliberately: supersonic wind-tunnel diffusers, engine inlets, and the shock diamonds in rocket exhausts are all managed shock systems. The Rayleigh Pitot formula converts supersonic Pitot readings to Mach number by accounting for the normal shock ahead of the probe. In transonic wings, weak normal shocks terminate supersonic pockets; their oscillation causes buffet, controlled with vortex generators or shock-control bumps. Normal-shock tables - or the closed-form relations - are the everyday calculator.", "keys": ["Shocks are near-discontinuities where supersonic flow becomes subsonic.", "Pressure, density, temperature jump up; velocity and total pressure drop.", "Entropy rises - shocks are irreversible.", "Property ratios depend only on upstream Mach number.", "Weak oblique-shock sequences lose less total pressure than one normal shock."], "reqs": ["Upstream Mach number and static properties.", "Calorically perfect gas assumption (or real-gas tables).", "Shock location and boundary-layer interaction check for inlets."], "stds": ["Shock relations per NACA 1135 tables conventions.", "Total-pressure loss reported as p02/p01."], "cites": ["Anderson JD. Modern Compressible Flow. 3rd ed. McGraw-Hill; 2002.", "NACA Report 1135. Equations, Tables, and Charts for Compressible Flow; 1953."], "demo": "#!/usr/bin/env python3\n\"\"\"Normal shock relations vs upstream Mach (k=1.4).\"\"\"\nk = 1.4\nprint(\"  M1    p2/p1   rho2/rho1  T2/T1   M2    p02/p01\")\nfor M1 in (1.2, 1.5, 2.0, 2.5, 3.0):\n    p = 1 + 2*k/(k+1)*(M1**2-1)\n    r = ((k+1)*M1**2)/(2+(k-1)*M1**2)\n    M2 = ((1+(k-1)/2*M1**2)/(k*M1**2-(k-1)/2))**0.5\n    t1 = 1+(k-1)/2*M1**2; t2 = 1+(k-1)/2*M2**2\n    p02p01 = (t1/t2)**(k/(k-1)) * p\n    print(f\"  {M1:.1f}   {p:6.2f}    {r:6.3f}     {p/r:5.2f}   {M2:.3f}   {p02p01:.3f}\")\n"}, {"tier": "Compounded", "g": "Viscous Flows", "title": "Open-Channel Flow", "desc": "Open-channel flow - rivers, canals, spillways, storm drains - has a free surface at atmospheric pressure, so gravity rather than pressure drives it. The Froude number Fr = V/sqrt(g*y) replaces the Mach number as the key parameter: subcritical (Fr < 1) flow is deep and slow with disturbances traveling upstream; supercritical (Fr > 1) is shallow and fast with no upstream influence.\nUniform flow is described by the Manning equation, V = (1/n)*R^(2/3)*S^(1/2), an empirical workhorse using roughness coefficient n. Transitions from supercritical to subcritical happen through hydraulic jumps - turbulent, energy-dissipating discontinuities that stilling basins are designed to contain. Specific energy diagrams show the alternate depths carrying the same discharge.", "how": "Engineers use Manning's equation to size canals, culverts, and sewers for design discharges, choosing n from tables for concrete, earth, or riprap. Spillway and weir formulas - also empirical - rate flow over structures from upstream head. Hydraulic-jump calculations size stilling basins below dams so the jump stays on the apron instead of scouring the riverbed. Flood modeling solves the shallow-water equations, the open-channel analogue of Navier-Stokes, over terrain grids.", "keys": ["Free surface at atmospheric pressure; gravity drives the flow.", "Froude number Fr = V/sqrt(g*y): subcritical vs supercritical regimes.", "Manning equation: V = (1/n)*R^(2/3)*S^(1/2) for uniform flow.", "Hydraulic jumps convert supercritical to subcritical, dissipating energy.", "Alternate depths carry the same discharge at the same specific energy."], "reqs": ["Channel geometry: cross-section, slope, roughness n.", "Design discharge and downstream control.", "Subcritical vs supercritical regime check via Froude number."], "stds": ["Manning n values per standard open-channel tables.", "Flood studies per USACE HEC-RAS methodology."], "cites": ["Chow VT. Open-Channel Hydraulics. McGraw-Hill; 1959.", "Munson BR, Young DF, Okiishi TH. Fundamentals of Fluid Mechanics. 8th ed. Wiley; 2021."], "demo": "#!/usr/bin/env python3\n\"\"\"Manning uniform flow in a trapezoidal canal.\"\"\"\nimport math\nb, m, y, S, n = 3.0, 1.5, 1.2, 0.001, 0.025  # bottom width, side slope, depth, slope, n\nA = (b + m * y) * y\nP = b + 2 * y * math.sqrt(1 + m ** 2)\nR = A / P\nV = (1 / n) * R ** (2/3) * math.sqrt(S)\nFr = V / math.sqrt(9.81 * A / (b + 2*m*y))\nprint(f\"Q = {V*A:.2f} m3/s, V = {V:.2f} m/s, Fr = {Fr:.2f} (subcritical)\")\n"}, {"tier": "Compounded", "g": "Applications", "title": "Pump and Turbine Fundamentals", "desc": "Turbomachines transfer energy between a rotor and a fluid: pumps add head, turbines extract it. The Euler turbomachine equation ties head to the change in tangential velocity across the rotor, and velocity triangles at inlet and outlet make the energy transfer visible. Dimensionless groups - flow coefficient, head coefficient, power coefficient - collapse every pump's performance onto characteristic curves.\nSpecific speed selects the machine type: low specific speed means radial centrifugal pumps, high means axial flow. Cavitation - vapor bubbles forming where pressure drops below vapor pressure - limits suction performance, quantified by net positive suction head (NPSH). Affinity laws scale a pump's curves with impeller diameter and speed: Q with N*D^3, head with (N*D)^2, power with rho*(N*D)^3.", "how": "Engineers read pump curves at the system operating point where the pump head curve meets the system curve, checking efficiency and NPSH margin. Affinity laws predict performance after trimming an impeller or changing motor speed - the basis of variable-speed pumping for energy savings. Turbine selection for hydropower matches specific speed to head and flow: Pelton for high head, Francis for medium, Kaplan for low head high flow. Cavitation damage is avoided by keeping NPSH available above NPSH required with margin.", "keys": ["Euler turbomachine equation links head to tangential velocity change.", "Specific speed selects radial, mixed, or axial machines.", "Affinity laws: Q~ND^3, H~(ND)^2, P~rho(ND)^3.", "NPSH margin prevents cavitation damage.", "Operating point is where pump and system curves intersect."], "reqs": ["System curve: static head plus friction losses vs flow.", "Fluid properties and suction conditions for NPSH.", "Pump characteristic curves from the manufacturer."], "stds": ["Pump testing per Hydraulic Institute / ASME PTC 8.2.", "NPSH definitions per HI 9.6.1."], "cites": ["Cengel YA, Cimbala JM. Fluid Mechanics: Fundamentals and Applications. 4th ed. McGraw-Hill; 2017.", "Karassik IJ et al. Pump Handbook. 4th ed. McGraw-Hill; 2007."], "demo": "#!/usr/bin/env python3\n\"\"\"Pump affinity laws: scaling speed from N1 to N2.\"\"\"\nN1, N2 = 1450.0, 1750.0  # rpm\nQ1, H1, P1 = 0.10, 30.0, 45.0  # m3/s, m, kW at N1\nr = N2 / N1\nQ2, H2, P2 = Q1*r, H1*r**2, P1*r**3\nprint(f\"At {N2:.0f} rpm: Q={Q2:.3f} m3/s, H={H2:.1f} m, P={P2:.1f} kW\")\nprint(f\"(power rises with the cube: {r**3:.2f}x)\")\n"}, {"tier": "Compounded", "g": "Applications", "title": "Flow Measurement: Venturi, Orifice, and Pitot", "desc": "Differential-pressure meters infer flow rate from the pressure drop across a constriction. The Venturi meter's smooth contraction gives the lowest permanent loss with discharge coefficients near 0.98; the orifice plate is cheap and simple but lossy, with coefficients around 0.6; the flow nozzle sits between. All follow Q = C_d*A_t*sqrt(2*dp/(rho*(1-beta^4))), where beta is the diameter ratio.\nPitot-static tubes measure local velocity from stagnation minus static pressure, the standard for airspeed. Magnetic and ultrasonic meters serve conductive or clean fluids without obstruction; Coriolis meters read mass flow directly with the highest accuracy. Selection balances accuracy, pressure loss, cost, and maintenance - custody transfer demands the best, process control accepts less.", "how": "Engineers size the beta ratio for a readable differential pressure at design flow, install with required straight-pipe runs upstream and downstream, and apply discharge-coefficient correlations from ISO 5167. Calibration against a primary standard trims the coefficient for critical service. Pitot traverses across a duct - log-Chebyshev point placement - average the velocity profile for total flow. Smart transmitters now compensate for temperature, pressure, and density in real time.", "keys": ["Venturi: accurate, low loss. Orifice: cheap, lossy. Nozzle: middle ground.", "Q = C_d*A_t*sqrt(2*dp/(rho*(1-beta^4))) governs them all.", "Pitot-static gives local velocity from stagnation minus static pressure.", "Straight-pipe runs upstream/downstream are mandatory for accuracy.", "Coriolis meters read mass flow directly with top accuracy."], "reqs": ["Fluid density at operating conditions.", "Beta ratio and discharge coefficient per ISO 5167.", "Adequate straight runs and calibrated dp transmitter."], "stds": ["Differential-pressure metering per ISO 5167.", "Pitot-traverse methods per ASME PTC 19.5."], "cites": ["Figliola RS, Beasley DE. Theory and Design for Mechanical Measurements. 7th ed. Wiley; 2019.", "White FM. Fluid Mechanics. 9th ed. McGraw-Hill; 2021."], "demo": "#!/usr/bin/env python3\n\"\"\"Venturi meter: flow from differential pressure.\"\"\"\nimport math\nrho, beta, Cd = 999.0, 0.5, 0.98\nD = 0.2  # inlet diameter m\nAt = math.pi*(beta*D)**2/4\nfor dp_kPa in (2, 10, 40):\n    Q = Cd*At*math.sqrt(2*dp_kPa*1000/(rho*(1-beta**4)))\n    print(f\"  dp={dp_kPa:3d} kPa -> Q={Q*1000:6.1f} L/s\")\n"}, {"tier": "Compounded", "g": "Fundamentals", "title": "Similarity and Model Testing", "desc": "Similarity theory lets small-scale tests predict full-scale behavior: geometric similarity (scaled shape), kinematic similarity (scaled velocities), and dynamic similarity (matched force ratios, i.e., dimensionless groups). Match the governing pi groups and the dimensionless solution is identical - the model test becomes the prototype.\nComplete similarity is often impossible: a ship model cannot match Froude and Reynolds numbers simultaneously at small scale, so naval architects match Froude and correct for friction. Wind tunnels pressurize or cool the air to raise Reynolds number on small models. The art lies in knowing which groups dominate and correcting for the rest - incomplete similarity handled honestly still beats untested design.", "how": "Test engineers choose the dominant group - Froude for free-surface ships, Mach and Reynolds for aircraft, Reynolds for pipe components - and design the facility to match it. Corrections handle the unmatched groups: boundary-layer trips force turbulent transition at low Re, and blockage corrections adjust for tunnel walls. Uncertainty analysis propagates measurement error to the full-scale prediction. Modern practice pairs every test campaign with CFD, each validating the other.", "keys": ["Three similarities: geometric, kinematic, dynamic.", "Matched dimensionless groups mean identical dimensionless solutions.", "Full similarity is often impossible - match the dominant group, correct the rest.", "Ships match Froude; aircraft match Mach and Reynolds.", "Trips, blockage corrections, and uncertainty analysis make tests honest."], "reqs": ["Governing dimensionless groups for the physics involved.", "Facility capable of the required group values.", "Correction methods for unmatched groups."], "stds": ["Wind-tunnel testing per AIAA standards.", "Ship-model testing per ITTC procedures."], "cites": ["White FM. Fluid Mechanics. 9th ed. McGraw-Hill; 2021.", "Barenblatt GI. Scaling. Cambridge University Press; 2003."], "demo": "#!/usr/bin/env python3\n\"\"\"Ship model: Froude scaling from model to ship.\"\"\"\nlam = 25.0  # scale ratio (ship/model)\nVm = 2.0  # model speed m/s\nVs = Vm * lam ** 0.5  # Froude scaling: V ~ sqrt(L)\nRm = 0.5  # model resistance N (measured)\n# Resistance scales with rho*V^2*L^2 (same fluid)\nRs = Rm * (Vs / Vm) ** 2 * lam ** 2 / 1000.0\nprint(f\"Ship speed: {Vs:.1f} m/s ({Vs*1.944:.1f} knots)\")\nprint(f\"Ship resistance (Froude-scaled): {Rs:.0f} kN\")\n"}, {"tier": "Advanced", "g": "Turbulence", "title": "Turbulence Modeling: RANS, LES, DNS", "desc": "Turbulence - chaotic, three-dimensional, eddying motion - is the default state of high-Reynolds flows and the hardest problem in classical physics. Direct Numerical Simulation (DNS) resolves every eddy down to the Kolmogorov scale but costs Re^3 grid points, limiting it to research Reynolds numbers. Large-Eddy Simulation (LES) resolves the big energy-carrying eddies and models only the small ones, affordable for complex unsteady flows like combustion.\nReynolds-Averaged Navier-Stokes (RANS) averages out all unsteadiness and models the Reynolds stresses - the k-epsilon, k-omega, and SST models are the industry workhorses for steady design. The closure problem (more unknowns than equations after averaging) means every model is an approximation tuned to canonical flows. Choosing among DNS, LES, and RANS is the central cost-vs-fidelity decision in computational fluid dynamics.", "how": "Engineers default to RANS SST for attached aerodynamic flows, switch to LES or DES for massively separated, vortex-dominated, or aeroacoustic problems, and reserve DNS for fundamental studies and model validation. Model constants are calibrated against flat plates, channel flow, and jets - applying them far outside calibration (strong curvature, rotation, buoyancy) needs skepticism and validation data. Grid-convergence studies and comparison with experiment remain mandatory; a turbulence model is a hypothesis until validated for the specific flow.", "keys": ["DNS resolves everything but costs ~Re^3 - research only at high Re.", "LES resolves large eddies, models small ones - for unsteady complex flows.", "RANS averages everything; k-epsilon, k-omega SST are the workhorses.", "The closure problem forces modeling - every model is tuned approximation.", "Model choice is the central cost-vs-fidelity decision in CFD."], "reqs": ["Reynolds number and flow character (attached, separated, buoyant).", "Validation data or canonical-flow calibration.", "Grid resolution matched to the chosen approach."], "stds": ["Turbulence-model verification per ASME V&V 20.", "Near-wall treatment documented (wall-resolved vs wall functions)."], "cites": ["Pope SB. Turbulent Flows. Cambridge University Press; 2000.", "Versteeg HK, Malalasekera W. An Introduction to Computational Fluid Dynamics. 2nd ed. Pearson; 2007."], "demo": "#!/usr/bin/env python3\n\"\"\"Turbulence: Kolmogorov scale vs Reynolds number (pipe flow).\"\"\"\nnu = 1.5e-5  # m2/s\nD = 0.1  # m\nprint(\"   Re        eta/D (Kolmogorov/length)\")\nfor Re in (4e3, 1e5, 1e6, 1e7):\n    eta_over_D = Re ** -0.75  # eta/L ~ Re^-3/4\n    n_points = Re ** (9/4)  # ~Re^3 scaling hint\n    print(f\"  {Re:.0e}    {eta_over_D:.2e}     DNS cells ~ {n_points:.1e}\")\n"}, {"tier": "Advanced", "g": "Turbulence", "title": "Computational Fluid Dynamics Fundamentals", "desc": "Computational Fluid Dynamics discretizes the Navier-Stokes equations on a mesh and solves them iteratively, turning calculus into algebra a computer can chew. The finite-volume method dominates because it enforces conservation cell by cell; finite-difference and finite-element variants serve niche needs. Space is divided into cells, time into steps, and derivatives into differences.\nA credible CFD study needs mesh independence (refine until the answer stops changing), validated boundary conditions, an appropriate turbulence treatment, and convergence to tight residuals. The method's power - full field data anywhere, parametric sweeps overnight - comes with the responsibility of verification and validation: a colorful contour plot proves nothing by itself. Best practice follows the ASME V&V standards from meshing to reporting.", "how": "Practitioners build the geometry, generate a mesh with boundary-layer resolution (y+ ~ 1 for wall-resolved, 30-100 with wall functions), set physical models, and iterate. They check mass and energy balances, run grid-convergence studies (Grid Convergence Index), and validate against experiment or canonical data before trusting design decisions. Parametric sweeps explore design space; adjoint methods compute sensitivities for optimization. Unsteady problems need time-step studies just as steady ones need mesh studies.", "keys": ["Finite-volume dominates: conservation enforced cell by cell.", "Mesh independence is mandatory - refine until answers stop changing.", "y+ ~ 1 for wall-resolved; 30-100 with wall functions.", "Validation against experiment or canonical data before design use.", "A contour plot proves nothing without V&V."], "reqs": ["Geometry, mesh with boundary-layer resolution, boundary conditions.", "Turbulence/transition model choice with justification.", "Grid-convergence and validation evidence."], "stds": ["Verification and validation per ASME V&V 20 and AIAA G-077.", "Residual convergence criteria documented (typically 1e-4 or better)."], "cites": ["Versteeg HK, Malalasekera W. An Introduction to Computational Fluid Dynamics. 2nd ed. Pearson; 2007.", "Ferziger JH, Peric M. Computational Methods for Fluid Dynamics. 3rd ed. Springer; 2002."], "demo": "#!/usr/bin/env python3\n\"\"\"1D convection-diffusion: upwind finite-volume on a tiny mesh.\"\"\"\nN, L, u, Gamma, phi0, phiL = 10, 1.0, 1.0, 0.1, 0.0, 1.0\ndx = L / N\nF, D = u, Gamma / dx  # convection, diffusion conductances\naW, aE, aP = D + max(F, 0), D + max(-F, 0), 0.0\naP = aW + aE\n# Thomas algorithm for tridiagonal system with Dirichlet ends\na = [0]+[-aW]*(N-1); b = [aP]*N; c = [-aE]*(N-1)+[0]\nd = [aW*phi0 if i == 0 else (aE*phiL if i == N-1 else 0.0) for i in range(N)]\nfor i in range(1, N):\n    w = a[i]/b[i-1]; b[i] -= w*c[i-1]; d[i] -= w*d[i-1]\nx = [0]*N; x[-1] = d[-1]/b[-1]\nfor i in range(N-2, -1, -1): x[i] = (d[i]-c[i]*x[i+1])/b[i]\nprint(\"node phi:\", \" \".join(f\"{v:.3f}\" for v in x))\n"}, {"tier": "Advanced", "g": "Compressible Flows", "title": "Aerodynamic Design of Wings", "desc": "Wing design balances lift, drag, and structure across the flight envelope. Airfoil selection sets the section lift curve, stall behavior, and drag bucket; planform - span, chord distribution, sweep, taper - sets induced drag and structural weight. The lift-to-drag ratio at cruise, often 15-20 for airliners, is the figure of merit that range equations convert directly into fuel burn.\nSweep delays transonic drag rise and raises critical Mach number; winglets recover some tip-vortex energy, cutting induced drag a few percent. High-lift devices - slats and multi-element flaps - double or triple maximum lift for takeoff and landing. Modern design iterates between panel codes, RANS CFD, and wind-tunnel validation, with multidisciplinary optimization trading aerodynamics against structures and systems.", "how": "Designers start from mission requirements (payload, range, speed) and use the Breguet range equation to set wing loading and target L/D. Airfoil families (NACA, supercritical) are screened with 2D analysis, then the 3D wing is shaped for an elliptical-ish lift distribution minimizing induced drag. Twist (washout) controls stall progression so the root stalls before the tip, preserving aileron authority. Every candidate flies in CFD and the tunnel before it flies for real.", "keys": ["L/D at cruise (15-20 for airliners) drives range via the Breguet equation.", "Sweep delays transonic drag rise; winglets cut induced drag.", "High-lift devices multiply max lift for takeoff and landing.", "Elliptical lift distribution minimizes induced drag.", "Washout makes the root stall first, keeping roll control."], "reqs": ["Mission: payload, range, cruise Mach, field length.", "Airfoil data: lift curve, drag bucket, stall behavior.", "Structural weight model for the aero-structural tradeoff."], "stds": ["Airfoil coordinates per standard NACA/supercritical definitions.", "Stall and handling qualities per FAR Part 25."], "cites": ["Anderson JD. Fundamentals of Aerodynamics. 6th ed. McGraw-Hill; 2016.", "Raymer DP. Aircraft Design: A Conceptual Approach. 6th ed. AIAA; 2018."], "demo": "#!/usr/bin/env python3\n\"\"\"Breguet range: effect of L/D on airliner range.\"\"\"\nimport math\nV, sfc = 250.0, 1.6e-5  # m/s, kg/(N-s)\nW0, W1 = 78000.0, 60000.0  # kg takeoff, landing\nfor LD in (12, 15, 18, 21):\n    R = V / sfc * LD * math.log(W0 / W1) / 1000.0\n    print(f\"  L/D={LD:2d} -> range {R:6.0f} km\")\n"}, {"tier": "Advanced", "g": "Compressible Flows", "title": "Supersonic Nozzle Design", "desc": "A converging-diverging (de Laval) nozzle accelerates gas to supersonic speeds: flow chokes at the throat (M = 1) when the pressure ratio is high enough, then expands supersonically in the diverging section. The area-Mach relation fixes the area ratio for any design exit Mach number, and the method of characteristics shapes the contour for shock-free, uniform exit flow.\nOff-design operation brings shocks inside the nozzle (overexpanded) or expansion fans outside (underexpanded), with the familiar shock-diamond pattern in rocket plumes. Nozzle efficiency is measured by the thrust coefficient and specific impulse. Rocket nozzles add regenerative cooling and altitude-compensating designs (aerospike, dual-bell) to handle the huge expansion ratios space flight demands.", "how": "Designers pick the design Mach number from mission delta-v, compute the area ratio from isentropic relations, and contour the nozzle with the method of characteristics for uniform exit flow. Boundary-layer displacement corrections adjust the geometric contour. Off-design performance is mapped with shock/expansion analysis to predict thrust loss and side loads during startup transients. Cooling-channel design runs in parallel - the throat sees the fiercest heat flux in the engine.", "keys": ["Choked throat (M=1) plus diverging section gives supersonic exit.", "Area-Mach relation sets the area ratio for the design Mach.", "Method of characteristics shapes shock-free contours.", "Overexpanded: shocks inside. Underexpanded: shock diamonds outside.", "Altitude compensation (aerospike, dual-bell) adapts expansion to ambient pressure."], "reqs": ["Design exit Mach and chamber conditions.", "Specific heat ratio and gas properties.", "Ambient pressure profile for off-design analysis."], "stds": ["Nozzle performance per standard isentropic/characteristics methods.", "Thrust coefficient and specific impulse in SI with reference conditions stated."], "cites": ["Anderson JD. Modern Compressible Flow. 3rd ed. McGraw-Hill; 2002.", "Sutton GP, Biblarz O. Rocket Propulsion Elements. 9th ed. Wiley; 2016."], "demo": "#!/usr/bin/env python3\n\"\"\"De Laval nozzle: area ratio for design Mach numbers (k=1.4).\"\"\"\nk = 1.4\nprint(\"  M_design   A/A*\")\nfor M in (1.5, 2.0, 2.5, 3.0, 4.0, 5.0):\n    t = 2/(k+1)*(1+(k-1)/2*M**2)\n    Ar = 1/M * t**( (k+1)/(2*(k-1)) )\n    print(f\"   {M:.1f}      {Ar:6.3f}\")\n"}, {"tier": "Advanced", "g": "Multiphase Flows", "title": "Cavitation and Its Control", "desc": "Cavitation is the formation and violent collapse of vapor bubbles where local pressure drops below vapor pressure - at propeller tips, pump inlets, and control valves. Collapse concentrates energy into microjets and shock waves that pit metal, erode impellers, and generate noise; the cavitation number sigma = (p - p_v)/(rho*V^2/2) predicts inception.\nBeyond damage, cavitation degrades performance: pumps lose head, propellers lose thrust, and valves choke. Supercavitating designs deliberately envelop bodies in a vapor cavity to slash drag for high-speed underwater projectiles. Control strategies include raising suction pressure (NPSH), smoothing pressure gradients by design, injecting air to cushion collapse, and using cavitation-resistant materials and coatings.", "how": "Engineers predict inception with sigma compared against critical values from model tests, then ensure operating sigma stays above it with margin. Pump suction design maximizes NPSH available; propeller design limits tip loading and uses skew to soften pressure peaks. When cavitation is unavoidable, hardened materials (stainless steels, stellite overlays) and scheduled inspection manage the damage. Acoustic monitoring detects inception long before visible erosion, enabling condition-based maintenance.", "keys": ["Vapor bubbles form below vapor pressure; collapse pits and erodes metal.", "Cavitation number sigma = (p-p_v)/(rho*V^2/2) predicts inception.", "Performance drops: pumps lose head, propellers lose thrust.", "NPSH margin is the primary pump-side defense.", "Supercavitation deliberately uses a vapor cavity to cut drag."], "reqs": ["Local pressure field and vapor pressure at operating temperature.", "Critical cavitation number for the geometry.", "NPSH available vs required with margin."], "stds": ["Cavitation testing per ITTC and HI procedures.", "NPSH margin guidance per Hydraulic Institute 9.6.1."], "cites": ["Brennen CE. Cavitation and Bubble Dynamics. Oxford University Press; 1995.", "Karassik IJ et al. Pump Handbook. 4th ed. McGraw-Hill; 2007."], "demo": "#!/usr/bin/env python3\n\"\"\"Cavitation check: sigma at a pump inlet vs critical.\"\"\"\np, p_v, rho, V = 60e3, 2.3e3, 999.0, 8.0  # Pa, Pa, kg/m3, m/s\nsigma = (p - p_v) / (0.5 * rho * V ** 2)\nsigma_crit = 1.2\nprint(f\"sigma = {sigma:.2f}, critical = {sigma_crit}\")\nprint(\"CAVITATION RISK\" if sigma < sigma_crit else \"margin OK\")\n"}, {"tier": "Advanced", "g": "Multiphase Flows", "title": "Multiphase Flow Regimes", "desc": "When gas and liquid (or liquid and solid) flow together, the mixture organizes into regimes - bubbly, slug, churn, annular in vertical pipes; stratified, wavy, slug in horizontal ones. Regime maps (Taitel-Dukler and successors) predict the pattern from superficial velocities, and each regime has its own pressure-drop and heat-transfer behavior.\nSlug flow's alternating gas pockets and liquid slugs hammer piping with unsteady forces; annular flow carries liquid as a wall film with a fast gas core, the norm in evaporators. Oil-gas pipelines, boiling water reactors, and chemical risers all live or die by regime prediction. Measurement is harder than single-phase: void fraction, phase velocities, and regime must all be determined, often with gamma densitometers or electrical tomography.", "how": "Engineers locate the operating point on a regime map, then apply regime-specific correlations for pressure drop (Lockhart-Martinelli and its descendants) and heat transfer. Pipeline design avoids slug flow where possible or designs slug catchers to absorb the liquid surges. In boiling systems, the critical heat flux marks the regime boundary where a vapor film blankets the wall and heat transfer collapses - the safety limit of reactors and high-heat-flux electronics cooling.", "keys": ["Gas-liquid flows organize into bubbly, slug, churn, annular, stratified regimes.", "Regime maps predict pattern from superficial velocities.", "Each regime needs its own pressure-drop and heat-transfer correlations.", "Slug flow hammers piping; slug catchers absorb the surges.", "Critical heat flux is the boiling safety limit."], "reqs": ["Superficial gas and liquid velocities.", "Pipe orientation, diameter, fluid properties.", "Regime map valid for the fluid pair and geometry."], "stds": ["Two-phase pressure drop per Lockhart-Martinelli framework.", "Flow-regime identification per standard visualization/tomography practice."], "cites": ["Brennen CE. Fundamentals of Multiphase Flow. Cambridge University Press; 2005.", "Wallis GB. One-Dimensional Two-Phase Flow. McGraw-Hill; 1969."], "demo": "#!/usr/bin/env python3\n\"\"\"Lockhart-Martinelli two-phase pressure-drop multiplier.\"\"\"\nimport math\n# turbulent-turbulent, Martinelli parameter X\nfor X in (0.1, 0.5, 1.0, 2.0, 10.0):\n    C = 20.0\n    phi_l2 = 1 + C / X + 1 / X ** 2\n    print(f\"  X={X:5.1f}  liquid-only multiplier phi_l^2 = {phi_l2:7.2f}\")\n"}, {"tier": "Advanced", "g": "Multiphase Flows", "title": "Magnetohydrodynamics Basics", "desc": "Magnetohydrodynamics (MHD) couples fluid motion with electromagnetism for electrically conducting fluids - plasmas, liquid metals, salt water. The magnetic Reynolds number measures whether the flow drags field lines with it (high Rm, astrophysics) or the field diffuses through (low Rm, laboratory metals). The Lorentz force J x B acts as a body force on the fluid.\nApplications span fusion plasma confinement (tokamaks), electromagnetic pumping and stirring of molten metal, MHD power generation, and astrophysical jets. The Hartmann number measures magnetic vs viscous forces in duct flows; strong fields flatten velocity profiles and suppress turbulence. Alfven waves - magnetic tension waves in plasmas - are the MHD analogue of sound.", "how": "Engineers design electromagnetic pumps with traveling magnetic fields that push liquid metal without moving parts, used in nuclear cooling and aluminum casting. Fusion researchers shape magnetic bottles to confine plasma while fighting MHD instabilities (kink, tearing modes) that break confinement. In metallurgy, electromagnetic stirring homogenizes melts and controls solidification structure. Analysis adds the induction equation and Lorentz force to Navier-Stokes and solves the coupled system.", "keys": ["MHD = Navier-Stokes plus Maxwell for conducting fluids.", "Lorentz force J x B acts as a body force on the fluid.", "Magnetic Reynolds number: field frozen-in (high) vs diffusing (low).", "Hartmann number: magnetic vs viscous forces in ducts.", "Applications: fusion confinement, EM pumping, MHD power, astrophysics."], "reqs": ["Electrical conductivity of the fluid.", "Applied magnetic field strength and geometry.", "Magnetic Reynolds and Hartmann numbers for regime."], "stds": ["MHD notation per standard plasma-physics conventions.", "Fusion confinement reporting per ITER physics basis."], "cites": ["Davidson PA. An Introduction to Magnetohydrodynamics. Cambridge University Press; 2001.", "Freidberg JP. Plasma Physics and Fusion Energy. Cambridge University Press; 2007."], "demo": "#!/usr/bin/env python3\n\"\"\"Hartmann flow: magnetic damping of a duct profile.\"\"\"\nimport math\n# u/u0 = (cosh(Ha)-cosh(Ha*y/a))/(cosh(Ha)-1); center vs Ha\nfor Ha in (0.1, 2, 5, 10):\n    flat = 1 - 1 / math.cosh(Ha)  # normalized center velocity factor\n    print(f\"  Ha={Ha:4.1f}  profile flattening factor {flat:.3f}\")\n"}, {"tier": "Advanced", "g": "Applications", "title": "Microfluidics", "desc": "Microfluidics manipulates fluids in channels tens to hundreds of microns wide, where Reynolds numbers are tiny, flow is laminar and reversible, and surface forces dominate. Mixing must be engineered - with chaotic advection geometries or droplets - because turbulence will not do it. Diffusion across short distances becomes fast and useful.\nLab-on-a-chip devices integrate sample prep, reaction, and detection for point-of-care diagnostics, DNA sequencing, and drug screening, using nanoliters of reagent. Droplet microfluidics treats each droplet as an isolated microreactor, screening millions of variants per day. Soft lithography in PDMS made prototyping cheap; the field now pushes toward thermoplastics and paper for mass manufacture.", "how": "Designers lay out channel networks like circuits, using the hydraulic-electric analogy (pressure as voltage, flow as current, resistance from Poiseuille) to size channels. They validate with fluorescence microscopy and particle tracking, watching for bubbles - the bane of microfluidics. Surface chemistry (hydrophilic vs hydrophobic patterning) programs where droplets form and go. Scaling to product means injection-molded chips and integrated pumps, valves, and sensors.", "keys": ["Tiny channels: Re << 1, laminar, reversible, surface-dominated.", "No turbulent mixing - engineer it with geometry or droplets.", "Lab-on-a-chip: diagnostics, sequencing, screening on nanoliters.", "Hydraulic-electric analogy sizes channel networks.", "Bubbles and surface chemistry make or break devices."], "reqs": ["Channel dimensions and layout.", "Surface wetting properties and chemistry.", "Flow rates for the target Reynolds and Peclet numbers."], "stds": ["Microfluidic reporting per emerging ISO microfluidics standards.", "Biocompatibility per ISO 10993 for diagnostic devices."], "cites": ["Whitesides GM. The origins and the future of microfluidics. Nature 442:368-373; 2006.", "Bruus H. Theoretical Microfluidics. Oxford University Press; 2007."], "demo": "#!/usr/bin/env python3\n\"\"\"Microchannel: Reynolds and Peclet numbers.\"\"\"\nw, h, Q = 100e-6, 50e-6, 1e-9  # m, m, m3/s (1 uL/s)\nrho, mu, Dmol = 1000.0, 1e-3, 1e-9  # kg/m3, Pa-s, m2/s\nDh = 2*w*h/(w+h); V = Q/(w*h)\nRe = rho*V*Dh/mu; Pe = V*w/Dmol\nprint(f\"Re = {Re:.2f} (laminar), Pe = {Pe:.1e}\")\nprint(f\"diffusion time across width: {(w**2/Dmol):.1f} s\")\n"}, {"tier": "Advanced", "g": "Applications", "title": "Wind Engineering and Building Aerodynamics", "desc": "Wind engineering predicts wind loads on structures and pedestrian comfort around them. The atmospheric boundary layer - wind speed growing with height following log or power laws - sets the incoming flow; turbulence intensity and gust factors convert mean winds to design loads. Pressure coefficients measured in boundary-layer wind tunnels map onto cladding and structural frames.\nTall buildings shed vortices that can lock into structural frequencies (hence tuned mass dampers in skyscrapers), and street canyons channel winds to uncomfortable or dangerous levels at ground. Codes (ASCE 7) codify the tunnel data into design pressures by exposure, height, and risk category. Long-span bridges add aeroelasticity: flutter and galloping destroyed Tacoma Narrows and shape every modern suspension bridge deck.", "how": "Engineers determine design wind speeds from maps and exposure, compute pressures with code coefficients, and test unusual shapes in boundary-layer tunnels with correctly scaled turbulence. For supertall or long-span structures, aeroelastic models or CFD check vortex-induced vibration and flutter. Pedestrian comfort studies use the Lawson criteria on simulated ground-level winds, mitigated with canopies, screens, and massing changes. Damping systems - tuned mass, tuned liquid, or active - keep accelerations within human-comfort limits.", "keys": ["Atmospheric boundary layer sets the incoming wind profile.", "Gust factors convert mean winds to design loads.", "Vortex shedding can lock into structural frequencies.", "Codes (ASCE 7) turn tunnel data into design pressures.", "Bridge decks must be checked for flutter and galloping."], "reqs": ["Design wind speed, exposure category, topography.", "Building geometry and dynamic properties.", "Pressure coefficients (code or tunnel)."], "stds": ["Wind loads per ASCE 7.", "Wind-tunnel testing per ASCE 49."], "cites": ["Simiu E, Scanlan RH. Wind Effects on Structures. 3rd ed. Wiley; 1996.", "Holmes JD. Wind Loading of Structures. 3rd ed. CRC Press; 2015."], "demo": "#!/usr/bin/env python3\n\"\"\"ASCE 7-style velocity pressure at height z.\"\"\"\nimport math\nV, Kd, Ke = 47.0, 0.85, 1.0  # m/s basic wind, directionality, ground elevation\nprint(\"   z (m)   Kz     qz (kPa)\")\nfor z in (5, 10, 30, 100, 300):\n    Kz = 2.01 * (z / 274.0) ** (2/9.5) if z >= 5 else 2.01 * (5/274.0) ** (2/9.5)\n    qz = 0.613 * Kz * Kd * Ke * V ** 2 / 1000.0\n    print(f\"  {z:6.0f}   {Kz:.2f}    {qz:.2f}\")\n"}, {"tier": "Advanced", "g": "Applications", "title": "Hemodynamics: Blood Flow Modeling", "desc": "Hemodynamics applies fluid mechanics to blood: pulsatile, viscous flow through elastic vessels. The Womersley number weighs pulsatile inertia against viscosity and sets the velocity profile shape - blunt in large arteries, parabolic in small ones. Wall shear stress regulates endothelial cell behavior; low and oscillating shear marks atherosclerosis-prone sites like bifurcations.\nClinical modeling builds patient-specific geometries from CT/MRI and solves pulsatile Navier-Stokes with Windkessel outlet boundary conditions representing downstream vasculature. Fractional flow reserve from CT (FFR-CT) computes pressure drops across coronary stenoses noninvasively. Aneurysm rupture risk, stent design, and artificial heart valves all lean on these simulations - with blood treated as Newtonian in large vessels and shear-thinning in small ones.", "how": "Modelers segment medical images into 3D vessel geometries, mesh with boundary-layer resolution, and impose measured or typical pulsatile inflow waveforms. Non-Newtonian models (Carreau-Yasuda) capture shear-thinning where it matters. Results - wall shear stress maps, pressure drops, residence times - feed clinical decisions and device design, validated against in vitro phantoms and clinical outcomes. Regulatory submissions for cardiovascular devices increasingly include simulation evidence under ASME V&V 40.", "keys": ["Womersley number sets pulsatile profile shape in arteries.", "Wall shear stress patterns predict atherosclerosis sites.", "Patient-specific CFD from CT/MRI with Windkessel outlets.", "FFR-CT computes coronary stenosis severity noninvasively.", "Blood is Newtonian in large vessels, shear-thinning in small ones."], "reqs": ["Patient or representative vessel geometry.", "Pulsatile inflow waveform and downstream boundary conditions.", "Blood rheology model appropriate to vessel size."], "stds": ["Cardiovascular simulation credibility per ASME V&V 40.", "Medical image segmentation quality documented per clinical standards."], "cites": ["Ku DN. Blood flow in arteries. Ann Rev Fluid Mech 29:399-434; 1997.", "Nichols WW, O'Rourke MF. McDonald's Blood Flow in Arteries. 6th ed. CRC Press; 2011."], "demo": "#!/usr/bin/env python3\n\"\"\"Womersley number in human arteries.\"\"\"\nimport math\nrho, mu, f = 1060.0, 3.5e-3, 1.2  # kg/m3, Pa-s, Hz\nomega = 2 * math.pi * f\nprint(\" vessel              R (mm)   alpha\")\nfor name, R in ((\"aorta\", 12), (\"carotid\", 4), (\"arteriole\", 0.05)):\n    alpha = R/1000 * math.sqrt(omega * rho / mu)\n    print(f\"  {name:12s}      {R:5.2f}   {alpha:5.1f}\")\n"}];
function buildRecord(seed,topic,sig){
  var title=topic.title+(sig?' (Signature Edition)':'');
  var desc=topic.desc;
  if(sig)desc='Signature original treatment. '+desc;
  return {
    id:(sig?'JAH-FLDYS-':PREFIX)+String(seed).padStart(6,'0'),
    t:title, g:topic.g, name:title, title:title,
    description:desc,
    how_it_works:topic.how,
    key_points:topic.keys,
    requirements:topic.reqs,
    standards:topic.stds,
    citations:topic.cites,
    src:sig?'signature':'public-harvest',
    ladder_rank:seed,
    ladder_tier:topic.tier.toLowerCase(),
    demo:{kind:'python',language:'python',program:topic.demo,
      note:'Working demonstration program for this record.'},
    _seed:seed
  };
}
function topicFor(seed,opts){
  opts=opts||{};
  var pool=TOPICS.filter(function(t){return !opts.field||t.tier===opts.field;});
  if(!pool.length)pool=TOPICS;
  var i=((seed-1)%pool.length+pool.length)%pool.length;
  return {topic:pool[i],index:TOPICS.indexOf(pool[i])};
}
function generate(seed,opts){
  var tf=topicFor(seed,opts);
  var sig=(opts&&opts.signature)||true;
  return buildRecord(tf.index+1,tf.topic,sig);
}
function validate(r){
  var e=[];
  if(!r||typeof r!=='object')return {ok:false,errors:['not an object']};
  var okId=new RegExp('^('+PREFIX.replace(/-/g,'\\-')+'|'+'JAH-FLDYS-'.replace(/-/g,'\\-')+')\\d{6}$').test(r.id||'');
  if(!okId)e.push('id');
  if(FIELDS.indexOf(capTier(r.ladder_tier))<0)e.push('tier');
  if(['public-harvest','signature'].indexOf(r.src)<0)e.push('src');
  if(!r.title)e.push('title');
  if(!r.description||r.description.length<40)e.push('description');
  if(!r.demo||!r.demo.program||r.demo.program.indexOf('print')<0)e.push('demo');
  return {ok:!e.length,errors:e};
}
function capTier(s){s=String(s||'');return s.charAt(0).toUpperCase()+s.slice(1);}
function driftCheck(record,sample){
  var dups=(sample||[]).filter(function(r){return r&&r.title===record.title&&r.ladder_tier===record.ladder_tier;});
  return dups.length?{ok:false,errors:['duplicate title+tier in archive sample']}:{ok:true,errors:[]};
}
var gen={version:'jahdb-fluid-dynamics-signature-1.0',generate:generate,validate:validate,driftCheck:driftCheck,fields:FIELDS};
if(typeof JAHDB!=='undefined'&&JAHDB.registerGenerator)JAHDB.registerGenerator('fluid-dynamics-signature',gen);
if(typeof module!=='undefined'&&module.exports)module.exports=gen;
})();
